/**
 * Zoned timestamp, JSON and OID frames captured byte for byte from live brokers.
 *
 * A raw socket client sent each statement to the cubrid/cubrid:11.4 image with
 * protocol version 7, so these bytes owe nothing to the decoder under test. The
 * 10.2, 11.0 and 11.2 images sent the same bytes for every statement but
 * `oidValue` (captured on 11.4 only) once the leading query handle is ignored,
 * which differs per session. Every statement
 * selects a second column 'after', so a decoder that misreads the length of
 * the value also corrupts that column. Provenance: docs/PROTOCOL_ORACLES.md.
 */
export interface ZonedFrame {
  sql: string;
  hex: string;
}

